compact/posix/opencode/ollama-embed/anth.copy:
# Keep generated configuration files out of version control.
echo .chunkhound.json >> .gitignore
# Configure ChunkHound with Ollama embeddings and Anthropic for research. Embedding and LLM providers are independent — either works without the other. Field details: https://chunkhound.ai/docs/configuration/
# You'll need: Anthropic API key
cat > .chunkhound.json <<'CHUNKHOUND_EOF'
{
  "embedding": {
    "provider": "openai",
    "model": "qwen3-embedding",
    "base_url": "http://localhost:11434/v1"
  },
  "llm": {
    "provider": "anthropic",
    "api_key": "<YOUR_ANTHROPIC_API_KEY>"
  }
}
CHUNKHOUND_EOF
# Configure OpenCode to connect to ChunkHound via MCP.
if [ -f opencode.json ]; then
cat <<'CHUNKHOUND_EOF'
opencode.json already exists — merge this block into it manually:
{
  "mcp": {
    "ChunkHound": {
      "type": "local",
      "command": [
        "chunkhound",
        "mcp"
      ]
    }
  }
}
CHUNKHOUND_EOF
else
cat > opencode.json <<'CHUNKHOUND_EOF'
{
  "mcp": {
    "ChunkHound": {
      "type": "local",
      "command": [
        "chunkhound",
        "mcp"
      ]
    }
  }
}
CHUNKHOUND_EOF
fi
# Build ChunkHound's search index for this project.
chunkhound index .

