    }
  }
}
CHUNKHOUND_EOF
else
cat > opencode.json <<'CHUNKHOUND_EOF'
{
  "mcp": {
    "ChunkHound": {
      "type": "local",
      "command": [
        "chunkhound",
        "mcp"
      ]
    }
  }
}
CHUNKHOUND_EOF
fi
